package com.zhibrary.borrow;
import com.zhibrary.book.Book; import com.zhibrary.user.User; import jakarta.persistence.*; import java.time.LocalDate;
@Entity @Table(name="borrow_records") public class BorrowRecord { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(optional=false) private User user; @ManyToOne(optional=false) private Book book; @Column(nullable=false) private LocalDate borrowedDate; @Column(nullable=false) private LocalDate dueDate; private LocalDate returnedDate; @Enumerated(EnumType.STRING) @Column(nullable=false) private BorrowStatus status=BorrowStatus.ACTIVE; private double fine; protected BorrowRecord(){} public BorrowRecord(User user,Book book,LocalDate borrowedDate,LocalDate dueDate){this.user=user;this.book=book;this.borrowedDate=borrowedDate;this.dueDate=dueDate;} public Long getId(){return id;} public User getUser(){return user;} public Book getBook(){return book;} public LocalDate getBorrowedDate(){return borrowedDate;} public LocalDate getDueDate(){return dueDate;} public LocalDate getReturnedDate(){return returnedDate;} public BorrowStatus getStatus(){return status;} public double getFine(){return fine;} public void returnBook(LocalDate date,double fine){returnedDate=date;this.fine=fine;status=BorrowStatus.RETURNED;} }
